package app.launcherin.fixture;
import android.app.*;import android.content.*;import android.os.*;import android.graphics.*;import android.media.*;import android.media.session.*;import android.media.browse.MediaBrowser;import android.service.media.MediaBrowserService;import android.view.KeyEvent;import java.util.*;
public final class MusicService extends MediaBrowserService {
 private MediaSession session;private String title="Fixture track",artist="Fixture artist";private boolean startedService,subtitle,buttonOnly,ignoreTransport,idOnly,rejectBrowser,privateControls;private long position=90000;private int state=PlaybackState.STATE_PAUSED;
 @Override public void onCreate(){super.onCreate();android.content.SharedPreferences saved=getSharedPreferences("queue",0);title=saved.getString("title",title);artist=saved.getString("artist",artist);position=saved.getLong("position",position);rejectBrowser=saved.getBoolean("reject_browser",false);privateControls=saved.getBoolean("private_controls",false);
 session=new MediaSession(this,"Launcherin test media session");session.setCallback(new MediaSession.Callback(){
  public void onPlay(){if(!buttonOnly&&!ignoreTransport&&!idOnly)resume();}
  public void onPause(){if(!buttonOnly&&!ignoreTransport){state=PlaybackState.STATE_PAUSED;publish();}}
  public void onPlayFromMediaId(String id,Bundle extras){title=id;artist="Media ID test";resume();}
  public void onSeekTo(long at){position=at;publish();}
  public void onSkipToNext(){title="Next fixture track";publish();}
  public void onSkipToPrevious(){title="Previous fixture track";publish();}
  public boolean onMediaButtonEvent(Intent intent){if(!buttonOnly&&!ignoreTransport)return super.onMediaButtonEvent(intent);KeyEvent event=intent.getParcelableExtra(Intent.EXTRA_KEY_EVENT);if(event==null)return false;if(event.getAction()==KeyEvent.ACTION_DOWN&&event.getRepeatCount()==0){int key=event.getKeyCode();artist="Media key test";if(key==KeyEvent.KEYCODE_MEDIA_PLAY)resume();else if(key==KeyEvent.KEYCODE_MEDIA_PAUSE){state=PlaybackState.STATE_PAUSED;publish();}else if(key==KeyEvent.KEYCODE_MEDIA_PLAY_PAUSE){if(state==PlaybackState.STATE_PLAYING){state=PlaybackState.STATE_PAUSED;publish();}else resume();}}return true;}
 });session.setFlags(MediaSession.FLAG_HANDLES_MEDIA_BUTTONS|MediaSession.FLAG_HANDLES_TRANSPORT_CONTROLS);setSessionToken(session.getSessionToken());getSystemService(NotificationManager.class).createNotificationChannel(new NotificationChannel("fixture","Sessão de teste",NotificationManager.IMPORTANCE_LOW));}
 @Override public int onStartCommand(Intent intent,int flags,int id){startedService=true;if(intent!=null&&!intent.getBooleanExtra("callback_start",false)){title=intent.getStringExtra("title")==null?title:intent.getStringExtra("title");artist=intent.getStringExtra("artist")==null?artist:intent.getStringExtra("artist");privateControls=intent.getBooleanExtra("private_controls",false);subtitle=intent.getBooleanExtra("subtitle",false);buttonOnly=intent.getBooleanExtra("button_only",false);ignoreTransport=intent.getBooleanExtra("ignore_transport",false);idOnly=intent.getBooleanExtra("id_only",false);rejectBrowser=intent.getBooleanExtra("reject_browser",false);if(intent.hasExtra("state"))state=intent.getIntExtra("state",state);if(intent.hasExtra("position"))position=intent.getLongExtra("position",position);}publish();return START_NOT_STICKY;}
 private void resume(){state=PlaybackState.STATE_PLAYING;publish();if(!startedService){startedService=true;startService(new Intent(this,MusicService.class).putExtra("callback_start",true));}}
 private void publish(){getSharedPreferences("queue",0).edit().putString("title",title).putString("artist",artist).putLong("position",position).putBoolean("reject_browser",rejectBrowser).putBoolean("private_controls",privateControls).apply();Bitmap art=Bitmap.createBitmap(64,64,Bitmap.Config.ARGB_8888);art.eraseColor(getPackageName().contains("spotify")?0xff1db954:0xffea3323);MediaMetadata.Builder metadata=new MediaMetadata.Builder().putString(subtitle?MediaMetadata.METADATA_KEY_DISPLAY_TITLE:MediaMetadata.METADATA_KEY_TITLE,title).putString(subtitle?MediaMetadata.METADATA_KEY_DISPLAY_SUBTITLE:MediaMetadata.METADATA_KEY_ARTIST,artist).putString(MediaMetadata.METADATA_KEY_MEDIA_ID,title).putLong(MediaMetadata.METADATA_KEY_DURATION,240000).putBitmap(MediaMetadata.METADATA_KEY_ALBUM_ART,art);session.setMetadata(metadata.build());long actions=idOnly?PlaybackState.ACTION_PLAY_FROM_MEDIA_ID:buttonOnly?PlaybackState.ACTION_PLAY_PAUSE:PlaybackState.ACTION_PLAY|PlaybackState.ACTION_PAUSE;session.setPlaybackState(new PlaybackState.Builder().setActions(actions|PlaybackState.ACTION_SEEK_TO|PlaybackState.ACTION_SKIP_TO_NEXT|PlaybackState.ACTION_SKIP_TO_PREVIOUS).setState(state,position,state==PlaybackState.STATE_PLAYING?1:0,SystemClock.elapsedRealtime()).build());session.setActive(true);Notification.Builder builder=new Notification.Builder(this,"fixture").setSmallIcon(android.R.drawable.ic_media_play).setContentTitle(title).setContentText(artist).setLargeIcon(art).setStyle(new Notification.MediaStyle().setMediaSession(session.getSessionToken()));
 if(privateControls)builder.addAction(new Notification.Action.Builder(android.R.drawable.ic_media_play,"Reproduzir",PendingIntent.getBroadcast(this,90,new Intent(this,PrivateResume.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE)).build());
 startForeground(1,builder.build());}
 @Override public BrowserRoot onGetRoot(String caller,int uid,Bundle hints){return rejectBrowser||privateControls?null:new BrowserRoot("fixture",null);}
 @Override public void onLoadChildren(String parent,Result<List<MediaBrowser.MediaItem>> result){result.sendResult(Collections.emptyList());}
 @Override public void onDestroy(){session.release();super.onDestroy();}
}
